function irradianceCanvas(data,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d'),im=ctx.createImageData(w,h);for(let k=0;k<data.length;k++){const rgb=displayRGB(data[k],settings.ambient,settings.exposureEV);for(let j=0;j<3;j++)im.data[k*4+j]=rgb[j];im.data[k*4+3]=255;}ctx.putImageData(im,0,0);return c;}
