function paintPanels(){$('serviceView').innerHTML=serviceHTML(design);const host=$('panelsView');host.replaceChildren();for(const p of design.panels){const f=document.createElement('figure'),c=document.createElement('canvas'),label=document.createElement('figcaption');c.width=p.nx*3;c.height=p.ny*3;const ctx=c.getContext('2d');ctx.scale(3,3);ctx.fillStyle='#dabd82';ctx.fillRect(0,0,p.nx,p.ny);ctx.fillStyle='#1c2219';ctx.beginPath();for(const loop of p.contourLoops){loop.forEach(([u,v],i)=>{const x=u+p.nx/2,y=p.ny/2-v;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.closePath();}ctx.fill('evenodd');label.textContent=['Правая стенка','Верхняя стенка','Левая стенка','Нижняя стенка'][p.face]+' · доля рисунка '+fmt(design.faceShares[p.face]*100,0)+'%';f.append(c,label);host.append(f);}}
