function metrics(){const q=quality,d=design;$('iou').textContent=fmt(q.iou*100)+'%';$('edges').textContent=fmt(q.edgeF1*100)+'%';$('outside').textContent=fmt((q.outsideShadow??q.extraShadow??0)*100,2)+'%';$('contrast').textContent=fmt(q.contrast*100)+'%';document.querySelector('.verdict').classList.toggle('good',q.accepted);$('verdict').textContent=q.accepted?'Боковые стенки прошли цифровую проверку':'Результат пока требует доработки';$('reasons').textContent=q.accepted?'Тень сравнивается с выбранным референсом: подготовленным эскизом или исходным фото. Основание, стойка, патрон, провода и передний экран учтены. Лишняя тень вне рисунка показана полностью, в том числе от основания; проверка паразитных штрихов выполняется за пределами основания и заднего бортика. Это расчёт, физическое испытание ещё не проведено.':q.reasons.join('. ');$('opticsInfo').textContent=`Корпус ${fmt(d.p.bodySide,0)} × ${fmt(d.p.bodySide,0)} мм. Нить по центру, ${fmt(d.p.sourceZ,0)} мм от стены. Рисунок ${fmt(d.p.wallWidth,0)} × ${fmt(d.height,0)} мм, центр Y=${fmt(d.q.imageY,0)} мм. Отверстия рассчитаны для бокового света.`;$('partsInfo').textContent=`Четыре фигурные стенки; ${d.triangles.length.toLocaleString('ru-RU')} треугольников в общей трассировке. Перемычек: ${d.bridges}. Паразитная тень за пределами основания: ${fmt((q.strayShadow??0)*100,2)}%. Малый передний экран закрывает прямую видимость нити. Его одиночный кронштейн даёт нижний штрих, он включён в результат. Проводка, разъём, патрон и крепёж включены в трассировку. Посадки номинальные. Доли одного силуэта: правая ${fmt(d.faceShares[0]*100,0)}%, верхняя ${fmt(d.faceShares[1]*100,0)}%, левая ${fmt(d.faceShares[2]*100,0)}%, нижняя ${fmt(d.faceShares[3]*100,0)}%.`;}
